`,qC=`// Node.js (Express) Custom Sync Source Endpoint (POST)
import express from "express";

const app = express();
app.use(express.json());

app.post("/api/v1/sync/target", (req, res) => {
  const { jsonrpc, id, method, params } = req.body;

  if (method === "tools/list") {
    return res.json({
      jsonrpc: "2.0",
      id,
      result: {
        tools: [
          {
            name: "resolve_cluster_node",
            description: "Fetches live node addresses from internal cluster",
            inputSchema: {
              type: "object",
              properties: {
                cluster_id: { type: "string", description: "Cluster name or ID" }
              },
              required: ["cluster_id"]
            }
          }
        ]
      }
    });
  }

  if (method === "tools/call") {
    const { name, arguments: args } = params;
    // Query CMDB, Consul, or service registry:
    return res.json({
      jsonrpc: "2.0",
      id,
      result: {
        target_host: "192.168.10.45",
        port: 3389,
        state: "running"
      }
    });
  }

  return res.status(404).json({
    jsonrpc: "2.0",
    id,
    error: { code: -32601, message: "Method not found" }
  });
});

app.listen(8080, () => console.log("Sync source service listening on port 8080"));
